{
  "requirements": [
    {
      "text": "The system shall continuously perform self‑diagnostics on all critical sensors (camera, radar, ultrasonic) and automatically disengage Autopilot with an audible/visual warning if any sensor degrades beyond defined confidence thresholds."
    },
    {
      "text": "The system shall enforce a maximum allowable driver inattention interval (e.g., no steering torque) of no more than 2 seconds, and if exceeded, issue escalating alerts and subsequently disengage Autosteer."
    },
    {
      "text": "The system shall limit Autopilot activation to road segments that meet predefined environmental criteria (e.g., clear weather, adequate lane marking visibility, road type) and automatically refuse activation or disengage when those criteria are violated."
    },
    {
      "text": "The system shall maintain a minimum safe following distance based on vehicle speed and road conditions, and must override TACC to increase gap if a faster‑approaching vehicle is detected in an adjacent lane."
    },
    {
      "text": "The system shall provide a deterministic, fail‑safe transition to manual control, ensuring that steering torque and braking authority are instantly returned to the driver without delay upon any disengagement event."
    },
    {
      "text": "The system shall detect and correctly classify non‑lane‑based obstacles (e.g., stopped trucks, motorcycles, construction zones) and initiate appropriate evasive actions, including emergency braking, even when lane markings are absent or ambiguous."
    },
    {
      "text": "The system shall log, in tamper‑evident storage, all sensor inputs, system state changes, driver alerts, and disengagement events with timestamps for post‑incident analysis."
    },
    {
      "text": "The system shall implement cybersecurity controls that validate all over‑the‑air updates and reject any unauthorized modification to safety‑critical software components."
    },
    {
      "text": "The system shall provide a redundancy path for steering actuation (e.g., dual‑channel motor control) such that a single‑point failure does not prevent the driver from regaining manual control."
    },
    {
      "text": "The system shall conduct periodic calibration checks of camera and radar alignment, and if calibration drifts exceed tolerance, notify the driver and prohibit Autopilot activation until service is performed."
    }
  ]
}
